//! Responses generated by the guard: protocol errors and policy refusals.
//!
//! Bodies are built as bytes so the request `id` is echoed as its raw token,
//! including integers beyond 64 bits.
//!
//! Design choices:
//! - `denial.httpStatus` applies to every policy refusal, in both styles.
//! - A refused batch uses `denial.httpStatus`, also when the only refused
//!   element has invalid `params`. Each refused element gets its own error
//!   (or tool result), every other request `batch_rejected`.
//! - With `revealGrantNames` and no grant that provides the level, the
//!   message omits the grants sentence and `data.requiredGrants` is `[]`.
//! - SSE-only means `Accept` lists `text/event-stream` and nothing that
//!   accepts JSON (`application/json`, `application/*` or `*/*`); entries
//!   with `q=0` are not counted.

use serde::Serialize;
use serde_json::value::RawValue;

use crate::config::{Config, DenialStyle};
use crate::decide::{grants_providing, ElementDecision, Reason, Refusal};
use crate::envelope::{EnvelopeError, HttpRefusal, ParamsDetail, RequestDetail};
use crate::ids::Id;

/// The `data.policy` value and the `_meta` namespace.
pub const POLICY_NAME: &str = "mcp-tool-annotation-guard";
pub const META_KEY: &str = "ai.p4a/mcp-tool-annotation-guard";
/// The `Allow` header of `method_not_allowed`.
pub const ALLOWED_METHODS: &str = "POST, GET, DELETE, OPTIONS, HEAD";

/// A response the guard sends instead of forwarding.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Reply {
    pub status: u16,
    /// Lowercase names. `content-length` is left to the gateway.
    pub headers: Vec<(&'static str, String)>,
    pub body: Vec<u8>,
}

/// A request the guard cannot safely interpret (protocol errors).
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ProtocolError {
    Parse,
    InvalidRequest(RequestDetail),
    InvalidParams { id: Id, detail: ParamsDetail },
    TooLarge,
    Encoded,
    MethodNotAllowed,
    Internal { id: Option<Id> },
}

impl From<EnvelopeError> for ProtocolError {
    fn from(err: EnvelopeError) -> ProtocolError {
        match err {
            EnvelopeError::Parse => ProtocolError::Parse,
            EnvelopeError::InvalidRequest(detail) => ProtocolError::InvalidRequest(detail),
            EnvelopeError::InvalidParams { id, detail } => {
                ProtocolError::InvalidParams { id, detail }
            }
        }
    }
}

impl From<HttpRefusal> for ProtocolError {
    fn from(refusal: HttpRefusal) -> ProtocolError {
        match refusal {
            HttpRefusal::MethodNotAllowed => ProtocolError::MethodNotAllowed,
            HttpRefusal::Encoded => ProtocolError::Encoded,
            HttpRefusal::TooLarge => ProtocolError::TooLarge,
        }
    }
}

impl ProtocolError {
    pub fn reason(&self) -> &'static str {
        match self {
            ProtocolError::Parse => "parse_error",
            ProtocolError::InvalidRequest(_) => "invalid_request",
            ProtocolError::InvalidParams { .. } => "invalid_params",
            ProtocolError::TooLarge => "too_large",
            ProtocolError::Encoded => "encoded",
            ProtocolError::MethodNotAllowed => "method_not_allowed",
            ProtocolError::Internal { .. } => "internal_error",
        }
    }

    pub fn detail(&self) -> Option<&'static str> {
        match self {
            ProtocolError::InvalidRequest(detail) => Some(detail.as_str()),
            ProtocolError::InvalidParams { detail, .. } => Some(detail.as_str()),
            _ => None,
        }
    }

    fn code(&self) -> i64 {
        match self {
            ProtocolError::Parse => -32700,
            ProtocolError::InvalidParams { .. } => -32602,
            ProtocolError::Internal { .. } => -32603,
            _ => -32600,
        }
    }

    fn status(&self) -> u16 {
        match self {
            ProtocolError::Parse | ProtocolError::InvalidRequest(_) => 400,
            ProtocolError::InvalidParams { .. } => 200,
            ProtocolError::TooLarge => 413,
            ProtocolError::Encoded => 415,
            ProtocolError::MethodNotAllowed => 405,
            ProtocolError::Internal { .. } => 500,
        }
    }

    fn id(&self) -> Option<&Id> {
        match self {
            ProtocolError::InvalidParams { id, .. } => Some(id),
            ProtocolError::Internal { id } => id.as_ref(),
            _ => None,
        }
    }

    fn message(&self) -> String {
        match self.detail() {
            Some(detail) => format!(
                "The gateway rejected this request ({}: {detail}).",
                self.reason()
            ),
            None => format!("The gateway rejected this request ({}).", self.reason()),
        }
    }
}

// --- wire shapes -------------------------------------------------------------------

#[derive(Serialize)]
struct Envelope<'a> {
    jsonrpc: &'static str,
    id: Option<Box<RawValue>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    error: Option<ErrorObject<'a>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    result: Option<ToolResult<'a>>,
}

#[derive(Serialize)]
struct ErrorObject<'a> {
    code: i64,
    message: String,
    data: Data<'a>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct Data<'a> {
    #[serde(skip_serializing_if = "Option::is_none")]
    policy: Option<&'static str>,
    reason: &'static str,
    #[serde(skip_serializing_if = "Option::is_none")]
    detail: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    tool: Option<&'a str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    tool_class: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    caller_level: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    required_level: Option<&'static str>,
    #[serde(skip_serializing_if = "Option::is_none")]
    required_grants: Option<Vec<&'a str>>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct ToolResult<'a> {
    content: [TextContent; 1],
    is_error: bool,
    #[serde(rename = "_meta")]
    meta: Meta<'a>,
}

#[derive(Serialize)]
struct TextContent {
    #[serde(rename = "type")]
    kind: &'static str,
    text: String,
}

#[derive(Serialize)]
struct Meta<'a> {
    #[serde(rename = "ai.p4a/mcp-tool-annotation-guard")]
    guard: Data<'a>,
}

fn raw_id(id: Option<&Id>) -> Option<Box<RawValue>> {
    id.and_then(|id| RawValue::from_string(id.raw().to_owned()).ok())
}

fn to_bytes(envelope: &Envelope<'_>) -> Vec<u8> {
    // Serialising these shapes cannot fail; an empty body would still be refused.
    serde_json::to_vec(envelope).unwrap_or_default()
}

fn error_body(id: Option<&Id>, code: i64, message: String, data: Data<'_>) -> Vec<u8> {
    to_bytes(&Envelope {
        jsonrpc: "2.0",
        id: raw_id(id),
        error: Some(ErrorObject {
            code,
            message,
            data,
        }),
        result: None,
    })
}

// --- protocol errors -----------------------------------------------------------------

fn protocol_body(err: &ProtocolError) -> Vec<u8> {
    let data = Data {
        policy: Some(POLICY_NAME),
        reason: err.reason(),
        detail: err.detail(),
        ..Data::empty()
    };
    error_body(err.id(), err.code(), err.message(), data)
}

/// The reply for a protocol error. Audit mode is applied by the caller.
pub fn protocol_error(err: &ProtocolError, sse_only: bool) -> Reply {
    let mut reply = finish(err.status(), protocol_body(err), sse_only);
    if *err == ProtocolError::MethodNotAllowed {
        reply.headers.push(("allow", ALLOWED_METHODS.to_owned()));
    }
    reply
}

// --- policy refusals ------------------------------------------------------------------

impl<'a> Data<'a> {
    fn empty() -> Data<'a> {
        Data {
            policy: None,
            reason: "",
            detail: None,
            tool: None,
            tool_class: None,
            caller_level: None,
            required_level: None,
            required_grants: None,
        }
    }
}

fn with_hint(message: String, config: &Config) -> String {
    match &config.denial.hint {
        Some(hint) => format!("{message} {hint}"),
        None => message,
    }
}

/// Message and data for one refused call (message templates).
fn refusal_parts<'a>(refusal: &'a Refusal, config: &'a Config) -> (String, Data<'a>) {
    let tool = refusal.tool.as_str();
    let mut data = Data {
        reason: refusal.reason.as_str(),
        tool: Some(tool),
        ..Data::empty()
    };
    let message = match (refusal.reason, refusal.class) {
        (Reason::LevelInsufficient, Some(class)) => {
            data.tool_class = Some(class.as_str());
            data.caller_level = Some(refusal.caller_level.as_str());
            let mut message = format!(
                "Tool '{tool}' is classified as {}. Your access level is {}.",
                class.as_str(),
                refusal.caller_level.as_str()
            );
            if config.denial.include_required_level {
                data.required_level = Some(class.level().as_str());
                message.push_str(&format!(" Required level: {}.", class.level().as_str()));
            }
            if config.denial.reveal_grant_names {
                let grants = grants_providing(config, class);
                if !grants.is_empty() {
                    message.push_str(&format!(" Grants that provide it: {}.", grants.join(", ")));
                }
                data.required_grants = Some(grants);
            }
            message
        }
        (Reason::ToolBlocked, _) => format!("Tool '{tool}' is blocked by gateway policy for all callers."),
        (Reason::PartitionUnavailable, _) => {
            "The gateway could not determine the catalog partition for this caller, so tool access is refused."
                .to_owned()
        }
        // `UnknownTool`, and `LevelInsufficient` without a class (not produced by `decide`).
        _ => format!(
            "Tool '{tool}' is not known to the gateway yet. Call tools/list, then retry. \
             If this persists, ask an administrator to classify the tool."
        ),
    };
    (with_hint(message, config), data)
}

fn refusal_body(refusal: &Refusal, id: &Id, config: &Config) -> Vec<u8> {
    let (message, mut data) = refusal_parts(refusal, config);
    match config.denial.style {
        DenialStyle::JsonRpcError => {
            data.policy = Some(POLICY_NAME);
            error_body(Some(id), config.denial.error_code, message, data)
        }
        DenialStyle::ToolResultError => to_bytes(&Envelope {
            jsonrpc: "2.0",
            id: raw_id(Some(id)),
            error: None,
            result: Some(ToolResult {
                content: [TextContent {
                    kind: "text",
                    text: message,
                }],
                is_error: true,
                meta: Meta { guard: data },
            }),
        }),
    }
}

/// The reply for a refused single `tools/call`.
pub fn policy_refusal(refusal: &Refusal, id: &Id, config: &Config, sse_only: bool) -> Reply {
    finish(
        config.denial.http_status,
        refusal_body(refusal, id, config),
        sse_only,
    )
}

fn batch_rejected_body(id: &Id, config: &Config) -> Vec<u8> {
    let message = with_hint(
        "Batch rejected because it contains a tool call that is not permitted.".to_owned(),
        config,
    );
    let data = Data {
        policy: Some(POLICY_NAME),
        reason: "batch_rejected",
        ..Data::empty()
    };
    error_body(Some(id), config.denial.error_code, message, data)
}

/// The reply for a batch with at least one refused element:
/// one response per request, in request order. Notifications get none.
pub fn batch_refusal(
    decisions: &[(Id, ElementDecision)],
    config: &Config,
    sse_only: bool,
) -> Reply {
    let mut body = b"[".to_vec();
    for (i, (id, decision)) in decisions.iter().enumerate() {
        if i > 0 {
            body.push(b',');
        }
        let element = match decision {
            ElementDecision::Call(crate::decide::CallDecision::Deny(refusal)) => {
                refusal_body(refusal, id, config)
            }
            ElementDecision::InvalidParams(detail) => {
                protocol_body(&ProtocolError::InvalidParams {
                    id: id.clone(),
                    detail: *detail,
                })
            }
            _ => batch_rejected_body(id, config),
        };
        body.extend_from_slice(&element);
    }
    body.push(b']');
    finish(config.denial.http_status, body, sse_only)
}

// --- framing -------------------------------------------------------------------------------

/// `true` when `Accept` lists `text/event-stream` and nothing that accepts
/// JSON, so the reply must be one SSE event.
pub fn wants_sse_only(accept: Option<&str>) -> bool {
    let Some(accept) = accept else {
        return false;
    };
    let mut sse = false;
    let mut json = false;
    for entry in accept.split(',') {
        let mut parts = entry.split(';');
        let media = parts.next().unwrap_or_default().trim().to_ascii_lowercase();
        let refused = parts.any(|param| {
            let mut kv = param.splitn(2, '=');
            let key = kv.next().unwrap_or_default().trim();
            let value = kv.next().unwrap_or_default().trim();
            key.eq_ignore_ascii_case("q") && value.parse::<f32>().is_ok_and(|q| q == 0.0)
        });
        if refused {
            continue;
        }
        match media.as_str() {
            "text/event-stream" => sse = true,
            "application/json" | "application/*" | "*/*" => json = true,
            _ => {}
        }
    }
    sse && !json
}

fn finish(status: u16, json: Vec<u8>, sse_only: bool) -> Reply {
    let (content_type, body) = if sse_only {
        let mut framed = b"event: message\ndata: ".to_vec();
        framed.extend_from_slice(&json);
        framed.extend_from_slice(b"\n\n");
        ("text/event-stream", framed)
    } else {
        ("application/json", json)
    };
    Reply {
        status,
        headers: vec![
            ("content-type", content_type.to_owned()),
            ("cache-control", "no-store".to_owned()),
        ],
        body,
    }
}

#[cfg(test)]
// `serde_json::Value` indexing returns `Null` for a missing key or index; it never panics.
#[allow(clippy::indexing_slicing)]
mod tests {
    use super::*;
    use crate::config::{Class, Level};
    use crate::decide::CallDecision;
    use crate::ids::IdToken;
    use serde_json::{json, Value};

    fn config(value: Value) -> Config {
        Config::from_json(value.to_string().as_bytes()).unwrap_or_else(|err| unreachable!("{err}"))
    }

    fn id(raw: &str) -> Id {
        match Id::from_raw(raw) {
            IdToken::Valid(id) => id,
            _ => unreachable!("{raw}"),
        }
    }

    fn body_json(reply: &Reply) -> Value {
        serde_json::from_slice(&reply.body).unwrap_or_else(|err| unreachable!("{err}"))
    }

    fn header<'a>(reply: &'a Reply, name: &str) -> Option<&'a str> {
        reply
            .headers
            .iter()
            .find(|(n, _)| *n == name)
            .map(|(_, v)| v.as_str())
    }

    fn level_refusal() -> Refusal {
        Refusal {
            reason: Reason::LevelInsufficient,
            tool: "delete_branch".into(),
            caller_level: Level::Read,
            class: Some(Class::Destructive),
        }
    }

    fn refusal(reason: Reason) -> Refusal {
        Refusal {
            reason,
            tool: "t".into(),
            caller_level: Level::Read,
            class: None,
        }
    }

    // --- protocol errors ------------------------------------------------------------------

    #[test]
    fn protocol_error_table() {
        let cases = [
            (ProtocolError::Parse, -32700, 400, json!(null), None),
            (
                ProtocolError::InvalidRequest(RequestDetail::DuplicateKeys),
                -32600,
                400,
                json!(null),
                Some("duplicate_keys"),
            ),
            (
                ProtocolError::InvalidParams {
                    id: id("7"),
                    detail: ParamsDetail::NameTooLong,
                },
                -32602,
                200,
                json!(7),
                Some("name_too_long"),
            ),
            (ProtocolError::TooLarge, -32600, 413, json!(null), None),
            (ProtocolError::Encoded, -32600, 415, json!(null), None),
            (
                ProtocolError::MethodNotAllowed,
                -32600,
                405,
                json!(null),
                None,
            ),
            (
                ProtocolError::Internal {
                    id: Some(id("\"x\"")),
                },
                -32603,
                500,
                json!("x"),
                None,
            ),
            (
                ProtocolError::Internal { id: None },
                -32603,
                500,
                json!(null),
                None,
            ),
        ];
        for (err, code, status, expected_id, detail) in cases {
            let reply = protocol_error(&err, false);
            let body = body_json(&reply);
            assert_eq!(reply.status, status, "{err:?}");
            assert_eq!(body["jsonrpc"], "2.0");
            assert_eq!(body["id"], expected_id, "{err:?}");
            assert_eq!(body["error"]["code"], code, "{err:?}");
            assert_eq!(body["error"]["data"]["policy"], POLICY_NAME);
            assert_eq!(body["error"]["data"]["reason"], err.reason());
            assert_eq!(
                body["error"]["data"].get("detail").and_then(Value::as_str),
                detail
            );
            assert_eq!(header(&reply, "content-type"), Some("application/json"));
            assert_eq!(header(&reply, "cache-control"), Some("no-store"));
        }
    }

    #[test]
    fn protocol_messages_and_allow_header() {
        let reply = protocol_error(
            &ProtocolError::InvalidRequest(RequestDetail::EmptyBatch),
            false,
        );
        assert_eq!(
            body_json(&reply)["error"]["message"],
            "The gateway rejected this request (invalid_request: empty_batch)."
        );
        let reply = protocol_error(&ProtocolError::MethodNotAllowed, false);
        assert_eq!(header(&reply, "allow"), Some(ALLOWED_METHODS));
        assert_eq!(
            body_json(&reply)["error"]["message"],
            "The gateway rejected this request (method_not_allowed)."
        );
    }

    #[test]
    fn protocol_errors_never_carry_the_hint() {
        let c = config(json!({"denial": {"hint": "Ask #help."}}));
        let reply = protocol_error(&ProtocolError::Parse, false);
        assert!(!String::from_utf8_lossy(&reply.body).contains("#help"));
        let reply = policy_refusal(&refusal(Reason::ToolBlocked), &id("1"), &c, false);
        assert!(String::from_utf8_lossy(&reply.body).contains("for all callers. Ask #help."));
    }

    #[test]
    fn ids_are_echoed_as_raw_tokens() {
        let big = "123456789012345678901234567890";
        let reply = protocol_error(
            &ProtocolError::InvalidParams {
                id: id(big),
                detail: ParamsDetail::ParamsType,
            },
            false,
        );
        assert!(String::from_utf8_lossy(&reply.body).contains(&format!("\"id\":{big}")));
        let reply = policy_refusal(
            &refusal(Reason::UnknownTool),
            &id(r#""ab""#),
            &config(json!({})),
            false,
        );
        assert!(String::from_utf8_lossy(&reply.body).contains(r#""id":"ab""#));
    }

    // --- policy refusals ---------------------------------------------------------------------

    #[test]
    fn level_insufficient_matches_the_spec_example() {
        let c = config(json!({}));
        let reply = policy_refusal(&level_refusal(), &id("7"), &c, false);
        assert_eq!(reply.status, 200);
        assert_eq!(
            body_json(&reply),
            json!({
                "jsonrpc": "2.0",
                "id": 7,
                "error": {
                    "code": -32008,
                    "message": "Tool 'delete_branch' is classified as destructive. Your access level is read. Required level: destructive.",
                    "data": {
                        "policy": "mcp-tool-annotation-guard",
                        "reason": "level_insufficient",
                        "tool": "delete_branch",
                        "toolClass": "destructive",
                        "callerLevel": "read",
                        "requiredLevel": "destructive"
                    }
                }
            })
        );
    }

    #[test]
    fn tool_result_style_matches_the_spec_example() {
        let c = config(json!({"denial": {"style": "toolResultError"}}));
        let reply = policy_refusal(&level_refusal(), &id("7"), &c, false);
        assert_eq!(
            body_json(&reply),
            json!({
                "jsonrpc": "2.0",
                "id": 7,
                "result": {
                    "content": [{"type": "text", "text": "Tool 'delete_branch' is classified as destructive. Your access level is read. Required level: destructive."}],
                    "isError": true,
                    "_meta": {
                        "ai.p4a/mcp-tool-annotation-guard": {
                            "reason": "level_insufficient",
                            "tool": "delete_branch",
                            "toolClass": "destructive",
                            "callerLevel": "read",
                            "requiredLevel": "destructive"
                        }
                    }
                }
            })
        );
    }

    #[test]
    fn required_level_and_grant_names_are_optional() {
        let hidden = config(json!({"denial": {"includeRequiredLevel": false}}));
        let body = body_json(&policy_refusal(&level_refusal(), &id("1"), &hidden, false));
        assert_eq!(
            body["error"]["message"],
            "Tool 'delete_branch' is classified as destructive. Your access level is read."
        );
        assert!(body["error"]["data"].get("requiredLevel").is_none());
        assert!(body["error"]["data"].get("requiredGrants").is_none());

        let reveal = config(json!({
            "grants": [{"attribute": "admin", "level": "destructive"}, {"attribute": "ops", "level": "destructive"}],
            "denial": {"revealGrantNames": true}
        }));
        let body = body_json(&policy_refusal(&level_refusal(), &id("1"), &reveal, false));
        assert!(body["error"]["message"]
            .as_str()
            .is_some_and(|m| m
                .ends_with(" Required level: destructive. Grants that provide it: admin, ops.")));
        assert_eq!(
            body["error"]["data"]["requiredGrants"],
            json!(["admin", "ops"])
        );

        let none = config(json!({"denial": {"revealGrantNames": true}}));
        let body = body_json(&policy_refusal(&level_refusal(), &id("1"), &none, false));
        assert!(body["error"]["message"]
            .as_str()
            .is_some_and(|m| !m.contains("Grants")));
        assert_eq!(body["error"]["data"]["requiredGrants"], json!([]));
    }

    #[test]
    fn other_refusal_messages() {
        let c = config(json!({"denial": {"errorCode": -32001, "httpStatus": 403}}));
        let cases = [
            (Reason::ToolBlocked, "Tool 't' is blocked by gateway policy for all callers."),
            (
                Reason::UnknownTool,
                "Tool 't' is not known to the gateway yet. Call tools/list, then retry. If this persists, ask an administrator to classify the tool.",
            ),
            (
                Reason::PartitionUnavailable,
                "The gateway could not determine the catalog partition for this caller, so tool access is refused.",
            ),
        ];
        for (reason, message) in cases {
            let reply = policy_refusal(&refusal(reason), &id("1"), &c, false);
            let body = body_json(&reply);
            assert_eq!(reply.status, 403);
            assert_eq!(body["error"]["code"], -32001);
            assert_eq!(body["error"]["message"], message);
            assert_eq!(body["error"]["data"]["reason"], reason.as_str());
        }
    }

    #[test]
    fn names_are_json_escaped() {
        let r = Refusal {
            tool: "a\"b\u{1}".into(),
            ..refusal(Reason::ToolBlocked)
        };
        let body = body_json(&policy_refusal(&r, &id("1"), &config(json!({})), false));
        assert_eq!(body["error"]["data"]["tool"], "a\"b\u{1}");
    }

    // --- batches -------------------------------------------------------------------------------

    #[test]
    fn batch_refusal_answers_every_request_in_order() {
        let c = config(json!({"denial": {"hint": "See the wiki."}}));
        let decisions = vec![
            (
                id("1"),
                ElementDecision::Call(CallDecision::Allow {
                    class: Class::Read,
                    basis: crate::decide::Basis::Override,
                }),
            ),
            (
                id("2"),
                ElementDecision::Call(CallDecision::Deny(level_refusal())),
            ),
            (id("\"r\""), ElementDecision::NotACall),
            (
                id("4"),
                ElementDecision::InvalidParams(ParamsDetail::MissingToolName),
            ),
        ];
        let reply = batch_refusal(&decisions, &c, false);
        let body = body_json(&reply);
        assert_eq!(reply.status, 200);
        let reasons: Vec<&str> = body
            .as_array()
            .map(|items| {
                items
                    .iter()
                    .filter_map(|e| e["error"]["data"]["reason"].as_str())
                    .collect()
            })
            .unwrap_or_default();
        assert_eq!(
            reasons,
            vec![
                "batch_rejected",
                "level_insufficient",
                "batch_rejected",
                "invalid_params"
            ]
        );
        let ids: Vec<Value> = body
            .as_array()
            .map(|items| items.iter().map(|e| e["id"].clone()).collect())
            .unwrap_or_default();
        assert_eq!(ids, vec![json!(1), json!(2), json!("r"), json!(4)]);
        assert_eq!(
            body[0]["error"]["message"],
            "Batch rejected because it contains a tool call that is not permitted. See the wiki."
        );
        assert_eq!(body[0]["error"]["code"], -32008);
    }

    // --- framing ---------------------------------------------------------------------------------

    #[test]
    fn sse_only_accept_detection() {
        assert!(!wants_sse_only(None));
        assert!(wants_sse_only(Some("text/event-stream")));
        assert!(wants_sse_only(Some("Text/Event-Stream; charset=utf-8")));
        assert!(!wants_sse_only(Some("application/json, text/event-stream")));
        assert!(!wants_sse_only(Some("text/event-stream, */*")));
        assert!(!wants_sse_only(Some(
            "text/event-stream, application/*;q=0.1"
        )));
        assert!(wants_sse_only(Some(
            "text/event-stream, application/json;q=0"
        )));
        assert!(!wants_sse_only(Some("text/event-stream;q=0")));
        assert!(!wants_sse_only(Some("application/json")));
    }

    #[test]
    fn sse_framing() {
        let reply = protocol_error(&ProtocolError::Parse, true);
        assert_eq!(header(&reply, "content-type"), Some("text/event-stream"));
        let text = String::from_utf8_lossy(&reply.body);
        assert!(text.starts_with("event: message\ndata: {"));
        assert!(text.ends_with("}\n\n"));
        assert_eq!(text.matches('\n').count(), 3, "one data line");
    }
}
